# -*- coding: utf-8 -*-
# Класс «общий вопрос упражнения остался только у последнего подпункта» (разбиение упражнения на подпункты) + неверные ключи,
# найденные при разборе групп (свип tail_sweep, 152 группы, отобраны вручную). 26.09
import psycopg2
c = psycopg2.connect("postgresql://algo:algo_password@algo-content-db:5432/algo_content").cursor()
def ql(t):
    c.execute("SELECT regexp_replace(question_latex,'\\s+',' ','g') FROM tasks_master WHERE id=%s", (t,)); return c.fetchone()[0].strip()
S6 = "учебник (текст упражнения: общий вопрос после последнего подпункта) + пересчёт, 26.09"
S = "условие соседних подпунктов того же упражнения + пересчёт, 26.09"
P = {}
W = "подпункт упражнения без вопроса (общий вопрос упражнения остался только у последнего подпункта) — вопрос добавлен; ключ проверен: "
def app(t, tail, chk, src=S, **kw):
    P[t] = dict(q=ql(t).rstrip(" ;.,") + ". " + tail, why=W + chk, src=src, **kw)
# объём / площадь поверхности / периметр / сторона
for t, chk in [("G5_TB_52_1251.1", "2(18 + 21 + 42) = 162"), ("G5_TB_52_1251.2", "2(143 + 143 + 169) = 910")]: app(t, "Найдите площадь его поверхности.", chk)
for t, chk in [("G5_TB_52_1247.1", "2(54 + 78 + 117) = 498"), ("G5_TB_52_1247.2", "2(96 + 120 + 180) = 792")]: app(t, "Найдите площадь его поверхности.", chk)
for t, chk in [("G5_TB_54_1272.1", "6 · 12 · 7 = 504"), ("G5_TB_54_1267.1", "12 · 15 · 8 = 1440"), ("G5_TB_54_1268.1", "15 · 4 = 60")]: app(t, "Найдите его объём.", chk)
for t, chk in [("G5_TB_55_1295.1", "3 · 4 · 6 = 72"), ("G5_TB_55_1295.2", "1,2 · 2 · 3 = 7,2 дм³")]: app(t, "Найдите объём прямоугольного параллелепипеда.", chk)
app("G5_TB_54_1270.1", "Найдите площадь его основания.", "7290 : 54 = 135")
for t, chk in [("G5_TB_34_594.1", "4 · 32 = 128"), ("G5_TB_34_594.2", "4 · 8 = 32")]: app(t, "Найдите его периметр.", chk)
for t, chk in [("G5_TB_34_593.1", "2(8 + 2) = 20"), ("G5_TB_34_593.2", "2(12 + 20) = 64 см")]: app(t, "Найдите его периметр.", chk)
app("G5_TB_34_598.1", "Найдите его сторону.", "96 : 4 = 24")
app("G6_TB_51–52_454.1", "Сколько километров пройдёт поезд за один час?", "40,5 : 2/3 = 60,75 = 60 3/4")
for t, n, chk in [("G5_TB_67_1631.1", 17, "17 · 2,54 = 43,18"), ("G5_TB_67_1631.2", 19, "19 · 2,54 = 48,26")]:
    P[t] = dict(q=f"Диагональ монитора компьютера равна ${n}$ дюймам. Укажите размер монитора в сантиметрах, если $1$ дюйм равен $2{{,}}54$ см.", why=W + chk, src=S)
for t, chk in [("G5_TB_41_701.1", "3 + 3 = 6 < 10"), ("G5_TB_41_701.2", "5 + 5 = 10 — касаются")]: app(t, "Пересекаются ли эти окружности?", chk)
for t, chk in [("G5_TB_26_1003.1", "650 − 48 · 2 − 82 · 1 = 472"), ("G5_TB_26_1003.2", "650 − 48 · 3 − 82 · 2 = 342")]:
    app(t, "Расстояние от Москвы до Санкт-Петербурга $650$ км.", "без расстояния между городами задача не решается; " + chk)
app("G6_TB_21–23_197.1", "Ответ приведите к несократимой дроби.", "25/100 = 1/4, 50/100 = 1/2, 90/100 = 9/10")
# координатная прямая (школьный учебник 6: текст упражнений 705, 707, 708, 717, 718 сверен с OCR учебника)
for t, a, b in [("G6_TB_81–83_705.1", "-2", "2"), ("G6_TB_81–83_705.2", "3", "-3"), ("G6_TB_81–83_705.3", "-4", "4")]:
    P[t] = dict(q=f"На числовой оси обозначьте точки, соответствующие числам ${a}$ и ${b}$. На каком расстоянии от начала отсчёта лежат эти точки?", why=W + "|±n| = n", src=S6)
P["G6_TB_81–83_705.4"] = dict(q="На числовой оси обозначьте точки, соответствующие числам $1$ и $-1$. На каком расстоянии от начала отсчёта лежат эти точки?",
                              why="вопрос относился ко всем парам упражнения — формулировка приведена к одной паре; ключ 1 единица верен", src=S6)
for t, p, d, side in [("G6_TB_81–83_707.1", "A", "$2$ см $5$ мм", "левее"), ("G6_TB_81–83_707.2", "B", "$3$ см", "правее"),
                      ("G6_TB_81–83_707.3", "C", "$4$ см", "левее"), ("G6_TB_81–83_707.4", "D", "$5$ см $5$ мм", "правее")]:
    P[t] = dict(q=f"На координатной прямой с началом отсчёта $O$ и единичным отрезком $1$ см отметьте точку ${p}$, которая на {d} {side} точки $O$, и запишите её координату.",
                why=W + "единичный отрезок 1 см — как в ключах учебника (A(−2,5), B(3), C(−4), D(5,5))", src=S6)
for t, what in [("G6_TB_81–83_708.1", "правее числа $3$"), ("G6_TB_81–83_708.2", "правее числа $-5$"), ("G6_TB_81–83_708.3", "левее числа $-2$"), ("G6_TB_81–83_708.4", "левее числа $0$")]:
    P[t] = dict(q=f"На координатной прямой отметьте три точки {what} и запишите их координаты.", why=W + "ключ — три подходящие точки; все неверные варианты содержат точку вне луча или другое число точек", src=S6)
for t, n, k in [("G6_TB_81–83_717.1", "$+1$ единицу", 2), ("G6_TB_81–83_717.2", "$+2$ единицы", 3), ("G6_TB_81–83_717.3", "$-2$ единицы", -1),
                ("G6_TB_81–83_717.4", "$-1$ единицу", 0), ("G6_TB_81–83_717.5", "$-3$ единицы", -2)]:
    P[t] = dict(q=f"Точку $A(1)$ перенесли на {n}. Найдите координату полученной точки.", why=W + f"1 + ({n.strip('$').split('$')[0]}) = {k}", src=S6)
for t, what in [("G6_TB_81–83_718.1", "справа от числа $2$"), ("G6_TB_81–83_718.2", "справа от числа $-1$"), ("G6_TB_81–83_718.3", "слева от числа $-3{,}5$"), ("G6_TB_81–83_718.4", "слева от числа $0{,}5$")]:
    P[t] = dict(q=f"На числовой оси отметьте $3$ точки {what} и запишите их координаты.", why=W + "ключ — три подходящие точки, неверные варианты проверены", src=S6)
# неверные ключи
P["G6_TB_150–152_1166.1"] = dict(q=r"Площадь круга равна $36\pi$ см$^{2}$. Чему равна длина окружности этого круга?", k=r"$12\pi$ см", src=S,
    why="без вопроса подпункта ключом была сама данная площадь (36π см²); вопрос упражнения — длина окружности: r² = 36, r = 6, C = 2πr = 12π см; варианты заменены на неверные с описанием ошибки",
    dnew={0: (r"$6\pi$ см", "Ученик нашёл радиус r = 6 см и вычислил πr вместо 2πr."), 1: (r"$36\pi$ см", "Ученик решил, что длина окружности численно равна площади круга."),
          2: (r"$72\pi$ см", "Ученик умножил площадь на 2, спутав формулы S = πr² и C = 2πr.")})
P["G6_TB_150–152_1166.2"] = dict(q=r"Площадь круга равна $16\pi$ дм$^{2}$. Чему равна длина окружности этого круга?", k=r"$8\pi$ дм", src=S,
    why="без вопроса подпункта ключом была сама данная площадь (16π дм²); вопрос упражнения — длина окружности: r² = 16, r = 4, C = 2πr = 8π дм; варианты заменены на неверные с описанием ошибки",
    dnew={0: (r"$4\pi$ дм", "Ученик нашёл радиус r = 4 дм и вычислил πr вместо 2πr."), 1: (r"$16\pi$ дм", "Ученик решил, что длина окружности численно равна площади круга."),
          2: (r"$32\pi$ дм", "Ученик умножил площадь на 2, спутав формулы S = πr² и C = 2πr.")})
P["G6_TB_24_979.2"] = dict(k=r"$-1$ и $0$", src=S, why="ключ «−10 < −9,5 < −9» относился к числу −9,5 (другой подпункт); −1 < −0,63 < 0")
P["G6_TB_24_979.5"] = dict(k=r"$0$ и $1$", src=S, why="ключ «87/100» — запись числа, а не ответ на вопрос; 0 < 0,87 < 1")
P["G5_TB_32_1233.2"] = dict(k=r"$576{,}2$ см", src=S, why="ключи подпунктов «в сантиметрах» и «в дециметрах» перепутаны (и разорваны запятой): 5 м 7 дм 6 см 2 мм = 576,2 см")
P["G5_TB_32_1233.3"] = dict(k=r"$57{,}62$ дм", src=S, why="ключи подпунктов «в сантиметрах» и «в дециметрах» перепутаны (и разорваны запятой): 5 м 7 дм 6 см 2 мм = 57,62 дм; вариант «57,62 дм» был верным ответом")
P["G5_TB_32_1233.1"] = dict(src=S, drop=[0], why="вариант «5,762» (без единицы) равен ключу 5,762 м — закрыт, добавлен неверный вариант с описанием ошибки",
    dadd=[(r"$5{,}0762$ м", "Ученик записал 7 дм как сотые доли метра (0,07 м), а 6 см — как тысячные (0,006 м).")])
P["G5_TB_33_1284.2"] = dict(k=r"$\dfrac{1}{64}$", src=S, why="ключи подпунктов «одна клетка» и «3 ряда» перепутаны: одна клетка = 1/64 доски")
P["G5_TB_33_1284.3"] = dict(k=r"$\dfrac{3}{8}$", src=S, why="ключи подпунктов «одна клетка» и «3 ряда» перепутаны: 3 ряда = 3 · 8/64 = 3/8 доски")
P["G5_TB_31_1184.5"] = dict(k=r"$0{,}605$ т $< 691{,}3$ кг", src=S, why="десятичные дроби в ключе разорваны запятой («0, 605 т < 691, 3 кг»); 0,605 т = 605 кг < 691,3 кг")
P["G5_TB_21_846.4"] = dict(qrep=(r"c=17$ см", r"c=17$ дм"), src="по смыслу: ключ учебника ab = 64 дм² = 1088 : 17 возможен только при c = 17 дм, 26.09",
    why="опечатка единицы: при c = 17 см площадь основания была бы 640 дм², а не 64 дм²; единица приведена к дм")
P["G6_TB_81–83_687"] = dict(k=r"$1, 1, 1, 2, 5$", src="пересчёт, 26.09",
    why="ключ «1, 1, 1, 1, 1, 2, 3» неверен: сумма 10, но произведение 6; 1 + 1 + 1 + 2 + 5 = 10 и 1 · 1 · 1 · 2 · 5 = 10",
    dadd=[(r"$1, 1, 1, 1, 1, 2, 3$", "Ученик подобрал числа с суммой 10, но не проверил произведение: 1 · 1 · 1 · 1 · 1 · 2 · 3 = 6.")])
P["G6_TB_34–37_315"] = dict(qrep=("Найдите это число.", "Найдите большее из этих чисел."), src="школьный учебник 6 (OCR) + пересчёт, 26.09",
    why="«Найдите это число» неоднозначно (в учебнике так же): числа 2 1/5 и 1 1/2, а вариант 1 1/2 — меньшее из них; уточнено по смыслу ключа — большее")
